import React, { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import { User, Mail, Phone, BookOpen, GraduationCap, Award, CheckCircle2, X, Edit2, ChevronRight, Briefcase, Calendar, MapPin, ExternalLink } from 'lucide-react';
import { useStudents } from '../../hooks/useStudents';
import { useApplications } from '../../hooks/useApplications';

const StudentProfile = () => {
  const { id } = useParams();
  const { getStudentById, updateStudentProfile, loading: studentLoading } = useStudents();
  const { getApplicationsByStudent, loading: appLoading } = useApplications();

  const [student, setStudent] = useState(null);
  const [applications, setApplications] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showEditModal, setShowEditModal] = useState(false);
  const [formData, setFormData] = useState({});
  const [message, setMessage] = useState('');
  const [formLoading, setFormLoading] = useState(false);

  useEffect(() => {
    loadStudentProfile();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id]);

  const loadStudentProfile = async () => {
    try {
      setLoading(true);
      const [studentData, applicationsData] = await Promise.all([
        getStudentById(id),
        getApplicationsByStudent(id)
      ]);

      setStudent(studentData);
      setApplications(applicationsData);
      setFormData(studentData || {});
    } catch (error) {
      console.error('Failed to load student profile:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleEditProfile = () => {
    setFormData({
      ...student,
      skills: student.skills ? student.skills.join(', ') : '',
      certifications: student.certifications ? student.certifications.join(', ') : ''
    });
    setMessage('');
    setShowEditModal(true);
  };

  const handleInputChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setFormLoading(true);
    setMessage('');

    try {
      const updatedData = {
        ...formData,
        year: parseInt(formData.year),
        cgpa: parseFloat(formData.cgpa),
        skills: typeof formData.skills === 'string' ? formData.skills.split(',').map(s => s.trim()).filter(s => s) : formData.skills,
        certifications: typeof formData.certifications === 'string' ? formData.certifications.split(',').map(c => c.trim()).filter(c => c) : formData.certifications
      };

      await updateStudentProfile(id, updatedData);
      setMessage('Trajectory successfully synchronized.');

      setTimeout(() => {
        setShowEditModal(false);
        loadStudentProfile();
      }, 2000);
    } catch (error) {
      setMessage(error.message);
    } finally {
      setFormLoading(false);
    }
  };

  const getStatusBadge = (status) => {
    const statusConfig = {
      'under_review': 'bg-gold-500/10 text-gold-500 border-gold-500/20',
      'shortlisted': 'bg-blue-500/10 text-blue-400 border-blue-500/20',
      'accepted': 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20',
      'rejected': 'bg-rose-500/10 text-rose-400 border-rose-500/20'
    };

    const classes = statusConfig[status] || 'bg-pearl-800/10 text-pearl-600 border-pearl-800/20';
    return (
      <span className={`px-2.5 py-0.5 rounded-full text-[10px] font-bold border tracking-widest uppercase ${classes}`}>
        {status.replace('_', ' ')}
      </span>
    );
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center">
        <div className="w-12 h-12 border-4 border-charcoal-100 border-t-charcoal-800 rounded-full animate-spin"></div>
      </div>
    );
  }

  if (!student) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center p-6 text-charcoal-500 font-nexed italic">
        Student not found.
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background pb-24 font-sans text-charcoal-800">
      {/* Header Area */}
      <div className="h-80 bg-charcoal-900 relative overflow-hidden">
        <div className="absolute inset-0 bg-charcoal-gradient opacity-20"></div>
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[1000px] h-[1000px] bg-white/5 rounded-full blur-[150px]"></div>
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 -mt-40 relative z-10">

        {/* Top Profile Card */}
        <div className="bg-white rounded-[2.5rem] p-8 md:p-12 mb-10 border border-charcoal-100 shadow-xl flex flex-col md:flex-row gap-10 items-center md:items-start">
          <div className="w-40 h-40 md:w-52 md:h-52 rounded-3xl bg-charcoal-50 p-4 shadow-2xl shrink-0 border border-charcoal-100 overflow-hidden relative group">
            <img 
              src={student.profilePicture || 'https://via.placeholder.com/200x200?text=Student'} 
              alt="Profile" 
              className="w-full h-full object-cover rounded-2xl group-hover:scale-105 transition-all duration-500"
            />
            <div className="absolute inset-0 bg-black/5 opacity-0 group-hover:opacity-100 transition-opacity"></div>
          </div>

          <div className="flex-1 w-full text-center md:text-left">
            <div className="flex flex-col md:flex-row md:justify-between md:items-start gap-6">
              <div>
                <div className="flex flex-col md:flex-row items-center md:items-center gap-4 mb-4">
                  <h1 className="text-4xl md:text-6xl font-nexed font-bold text-charcoal-900 tracking-tight leading-none">{student.name}</h1>
                  {student.isEligible ? (
                    <div className="flex items-center gap-2 bg-emerald-600/10 text-emerald-600 px-3 py-1 rounded-full text-[10px] font-nexed font-black border border-emerald-600/20 uppercase tracking-widest">
                      <CheckCircle2 size={14} /> Eligible
                    </div>
                  ) : (
                    <div className="flex items-center gap-2 bg-rose-600/10 text-rose-600 px-3 py-1 rounded-full text-[10px] font-nexed font-black border border-rose-600/20 uppercase tracking-widest">
                      <X size={14} /> Not Eligible
                    </div>
                  )}
                </div>
                <p className="text-xl text-charcoal-500 font-light mb-6 flex items-center justify-center md:justify-start gap-3">
                  <GraduationCap size={24} className="text-charcoal-800"/> {student.department} • Year {student.year}
                </p>

                <div className="flex flex-wrap justify-center md:justify-start gap-4">
                  <span className="px-4 py-2 bg-onyx-800/50 text-pearl-500 rounded-xl text-sm font-medium border border-pearl-900/10 flex items-center gap-2">
                    <BookOpen size={18} className="text-gold-500/50"/> {student.studentId}
                  </span>
                  <span className="px-4 py-2 bg-onyx-800/50 text-pearl-500 rounded-xl text-sm font-medium border border-pearl-900/10 flex items-center gap-2">
                    <Award size={18} className="text-gold-500/50"/> CGPA: {student.cgpa}
                  </span>
                </div>
              </div>

              <div className="flex gap-4 w-full md:w-auto shrink-0 pt-4 md:pt-0">
                <button onClick={handleEditProfile} className="flex-1 md:flex-none flex items-center justify-center gap-2 px-8 py-3.5 glass text-white font-bold rounded-2xl hover:bg-white/5 transition-all border border-pearl-900/20">
                  <Edit2 size={18} /> Edit Profile
                </button>
              </div>
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">

          {/* Left Column */}
          <div className="space-y-10">

            {/* Contact Details */}
            <div className="glass rounded-[2rem] border border-pearl-900/10 p-10">
              <h3 className="text-2xl font-serif font-bold text-white mb-8 flex items-center gap-3">
                <div className="w-1.5 h-6 bg-gold-500 rounded-full"></div>
                Connection
              </h3>
              <ul className="space-y-8">
                <li className="flex items-start gap-5 group">
                  <div className="w-12 h-12 rounded-2xl bg-onyx-800 text-gold-500 flex items-center justify-center shrink-0 group-hover:bg-gold-500 group-hover:text-onyx-900 transition-all border border-pearl-900/10">
                    <Mail size={22} />
                  </div>
                  <div>
                    <p className="text-xs font-bold text-pearl-700 uppercase tracking-widest mb-1">Email Address</p>
                    <a href={`mailto:${student.email}`} className="text-pearl-200 font-bold hover:text-gold-500 transition-colors break-all">
                      {student.email}
                    </a>
                  </div>
                </li>
                <li className="flex items-start gap-5 group">
                  <div className="w-12 h-12 rounded-2xl bg-onyx-800 text-gold-500 flex items-center justify-center shrink-0 group-hover:bg-gold-500 group-hover:text-onyx-900 transition-all border border-pearl-900/10">
                    <Phone size={22} />
                  </div>
                  <div>
                    <p className="text-xs font-bold text-pearl-700 uppercase tracking-widest mb-1">Phone Number</p>
                    <a href={`tel:${student.phone}`} className="text-pearl-200 font-bold hover:text-gold-500 transition-colors">
                      {student.phone}
                    </a>
                  </div>
                </li>
              </ul>
            </div>

            {/* Technical Arsenal */}
            <div className="glass rounded-[2rem] border border-pearl-900/10 p-10">
              <h3 className="text-2xl font-serif font-bold text-white mb-8">Technical Arsenal</h3>
              {student.skills && student.skills.length > 0 ? (
                <div className="flex flex-wrap gap-3">
                  {student.skills.map(skill => (
                    <span key={skill} className="px-4 py-2 bg-onyx-800 text-pearl-400 rounded-xl text-xs font-bold border border-pearl-900/10 uppercase tracking-tighter hover:border-gold-500/30 hover:text-gold-500 transition-all cursor-default">
                      {skill}
                    </span>
                  ))}
                </div>
              ) : (
                <p className="text-pearl-600 italic">No skills cataloged yet.</p>
              )}
            </div>

            {/* Academic Accolades */}
            <div className="glass rounded-[2rem] border border-pearl-900/10 p-10 bg-onyx-gradient">
              <h3 className="text-2xl font-serif font-bold text-white mb-8">Certifications</h3>
              {student.certifications && student.certifications.length > 0 ? (
                <ul className="space-y-6">
                  {student.certifications.map((cert, index) => (
                    <li key={index} className="flex items-start gap-4 group">
                      <div className="w-10 h-10 rounded-xl bg-gold-gradient text-onyx-900 flex items-center justify-center shrink-0 shadow-gold group-hover:scale-110 transition-transform">
                        <Award size={20} />
                      </div>
                      <span className="text-pearl-200 font-medium leading-tight pt-2">{cert}</span>
                    </li>
                  ))}
                </ul>
              ) : (
                <p className="text-pearl-600 italic">Seeking further excellence.</p>
              )}
            </div>

          </div>

          {/* Right Column */}
          <div className="lg:col-span-2 space-y-10">

            {/* Academic Standing */}
            <div className="glass rounded-[2.5rem] border border-pearl-900/10 p-10 shadow-xl overflow-hidden relative">
              <div className="absolute top-0 right-0 p-8">
                <GraduationCap size={120} className="text-gold-500/5 rotate-12" />
              </div>
              <h3 className="text-3xl font-serif font-bold text-white mb-10">Academic Portfolio</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-10 relative z-10">
                <div className="space-y-8">
                  <div>
                    <p className="text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3">Academic Major</p>
                    <p className="text-xl font-bold text-white leading-none">{student.department}</p>
                  </div>
                  <div>
                    <p className="text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3">Seniority Level</p>
                    <p className="text-xl font-bold text-white leading-none">Year {student.year}</p>
                  </div>
                </div>
                <div className="space-y-8">
                  <div>
                    <p className="text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3">Merit Quotient</p>
                    <div className="flex items-baseline gap-2">
                      <span className="text-5xl font-serif font-black text-gold-500">{student.cgpa}</span>
                      <span className="text-pearl-600 font-bold">/ 10.0</span>
                    </div>
                  </div>
                  <div>
                    <p className="text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3">Corporate Status</p>
                    {student.isEligible ? (
                      <span className="text-emerald-400 font-bold uppercase tracking-widest text-xs flex items-center gap-2">
                        <div className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></div> Placements Active
                      </span>
                    ) : (
                      <span className="text-rose-400 font-bold uppercase tracking-widest text-xs flex items-center gap-2">
                         Pending Validation
                      </span>
                    )}
                  </div>
                </div>
              </div>
            </div>

            {/* Application Trajectory */}
            <div className="glass rounded-[2.5rem] border border-pearl-900/10 overflow-hidden shadow-xl">
              <div className="px-10 py-8 border-b border-pearl-900/10 flex justify-between items-center bg-white/5">
                <div>
                  <h3 className="text-2xl font-serif font-bold text-white">Application Trajectory</h3>
                  <p className="text-pearl-500 text-sm mt-1 font-light tracking-wide">Tracking your global career pursuits.</p>
                </div>
                <div className="w-12 h-12 rounded-2xl bg-onyx-800 flex items-center justify-center text-gold-500 font-bold border border-pearl-900/10">
                  {applications.length}
                </div>
              </div>

              <div className="p-0">
                {applications.length > 0 ? (
                  <div className="overflow-x-auto">
                    <table className="w-full text-left">
                      <thead>
                        <tr className="bg-onyx-950/50 text-pearl-700 text-[10px] uppercase tracking-[0.2em] font-black">
                          <th className="py-6 px-10">Strategic Role</th>
                          <th className="py-6 px-10">Institution</th>
                          <th className="py-6 px-10">Timeline</th>
                          <th className="py-6 px-10">Verdict</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-pearl-900/5">
                        {applications.map(application => (
                          <tr key={application.id} className="hover:bg-white/[0.02] transition-colors">
                            <td className="py-6 px-10">
                              <span className="font-bold text-white tracking-tight">{application.jobTitle}</span>
                            </td>
                            <td className="py-6 px-10">
                              <span className="text-pearl-400 flex items-center gap-2">
                                <Building2 size={16} className="text-gold-500/50" /> {application.company}
                              </span>
                            </td>
                            <td className="py-6 px-10">
                              <span className="text-pearl-600 text-sm tabular-nums">
                                {new Date(application.applicationDate).toLocaleDateString()}
                              </span>
                            </td>
                            <td className="py-6 px-10">{getStatusBadge(application.status)}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                ) : (
                  <div className="p-20 text-center">
                    <div className="w-20 h-20 bg-onyx-800 rounded-3xl flex items-center justify-center mx-auto mb-8 border border-pearl-900/10">
                      <Briefcase className="text-gold-500/30" size={32} />
                    </div>
                    <p className="text-pearl-600 font-light italic">Your professional journey begins with the first application.</p>
                  </div>
                )}
              </div>
            </div>

          </div>
        </div>
      </div>

      {/* Edit Profile Modal */}
      {showEditModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 sm:p-6 bg-onyx-950/80 backdrop-blur-md overflow-y-auto">
          <div className="glass rounded-[3rem] w-full max-w-3xl shadow-[0_0_50px_rgba(0,0,0,0.5)] border border-pearl-900/10 overflow-hidden my-auto animate-fade-in-up">
            <div className="px-10 py-8 border-b border-pearl-900/10 flex justify-between items-center bg-white/5">
              <h3 className="text-2xl font-serif font-bold text-white">Refine Personal Brand</h3>
              <button onClick={() => setShowEditModal(false)} className="text-pearl-600 hover:text-white bg-onyx-800 p-2.5 rounded-xl transition-all border border-pearl-900/10">
                <X size={20} />
              </button>
            </div>

            <div className="p-10 max-h-[70vh] overflow-y-auto custom-scrollbar">
              {message && (
                <div className={`p-5 rounded-2xl mb-8 font-bold text-sm uppercase tracking-widest flex items-start gap-4 ${message.includes('successfully') ? 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/20' : 'bg-rose-500/10 text-rose-400 border border-rose-500/20'}`}>
                  {message.includes('successfully') ? <CheckCircle2 size={20} className="shrink-0" /> : <X size={20} className="shrink-0" />}
                  <p>{message}</p>
                </div>
              )}

              <form onSubmit={handleSubmit} className="space-y-8">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div>
                    <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3">Legal Name</label>
                    <input type="text" name="name" value={formData.name || ''} onChange={handleInputChange} required className="w-full px-5 py-4 rounded-2xl bg-onyx-800 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-medium text-white" />
                  </div>
                  <div>
                    <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3">Academic Email</label>
                    <input type="email" name="email" value={formData.email || ''} onChange={handleInputChange} required className="w-full px-5 py-4 rounded-2xl bg-onyx-800 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-medium text-white" />
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div>
                    <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3">Primary Phone</label>
                    <input type="tel" name="phone" value={formData.phone || ''} onChange={handleInputChange} required className="w-full px-5 py-4 rounded-2xl bg-onyx-800 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-medium text-white" />
                  </div>
                  <div>
                    <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3">Merit Quotient (CGPA)</label>
                    <input type="number" step="0.01" min="0" max="10" name="cgpa" value={formData.cgpa || ''} onChange={handleInputChange} required className="w-full px-5 py-4 rounded-2xl bg-onyx-800 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-medium text-white" />
                  </div>
                </div>

                <div>
                  <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3">Core Expertise</label>
                  <input type="text" name="skills" value={formData.skills || ''} onChange={handleInputChange} placeholder="React, Node.js, Python..." className="w-full px-5 py-4 rounded-2xl bg-onyx-800 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-medium text-white" />
                </div>

                <div>
                  <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3">Professional Accolades</label>
                  <textarea rows={3} name="certifications" value={formData.certifications || ''} onChange={handleInputChange} placeholder="AWS Certified, Google Data Analytics..." className="w-full px-5 py-4 rounded-2xl bg-onyx-800 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-light text-pearl-300 resize-none leading-relaxed" />
                </div>

                <div className="pt-8 flex gap-5 justify-end">
                  <button type="button" onClick={() => setShowEditModal(false)} disabled={formLoading} className="px-8 py-3.5 rounded-2xl font-bold text-pearl-500 glass hover:text-white transition-all">
                    Dismiss
                  </button>
                  <button type="submit" disabled={formLoading} className="px-8 py-3.5 rounded-2xl font-bold text-onyx-900 bg-gold-gradient hover:brightness-110 transition-all shadow-gold flex items-center gap-3">
                    {formLoading ? (
                       <><div className="w-4 h-4 border-2 border-onyx-900/30 border-t-onyx-900 rounded-full animate-spin"></div> Updating...</>
                    ) : 'Confirm Changes'}
                  </button>
                </div>
              </form>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

// Helper component for Building icon since it was used in Trajectory
const Building2 = ({ size, className }) => (
  <svg 
    width={size} 
    height={size} 
    viewBox="0 0 24 24" 
    fill="none" 
    stroke="currentColor" 
    strokeWidth="2" 
    strokeLinecap="round" 
    strokeLinejoin="round" 
    className={className}
  >
    <path d="M6 22V4a2 2 0 0 1 2-2h8a2 2 0 0 1 2 2v18Z" />
    <path d="M6 12H4a2 2 0 0 0-2 2v6a2 2 0 0 0 2 2h2" />
    <path d="M18 9h2a2 2 0 0 1 2 2v9a2 2 0 0 1-2 2h-2" />
    <path d="M10 6h4" />
    <path d="M10 10h4" />
    <path d="M10 14h4" />
    <path d="M10 18h4" />
  </svg>
);

export default StudentProfile;
